SELECT  FROM reports
WHERE user_id=#{userId} AND deleted_at IS NULL AND report_type=#{reportType} AND period_start=#{periodStart}
ORDER BY created_at DESC, id DESC

SELECT  FROM reports
WHERE user_id=#{userId} AND deleted_at IS NULL AND report_type=#{reportType} AND period_start=#{periodStart}
ORDER BY created_at DESC, id DESC

SELECT  FROM reports current_report
WHERE current_report.user_id=#{userId} AND current_report.deleted_at IS NULL AND current_report.report_type=#{reportType} AND current_report.period_start=#{periodStart}
  AND NOT EXISTS (
    SELECT 1 FROM reports next_report WHERE next_report.previous_report_id=current_report.id AND next_report.user_id=current_report.user_id
  )
ORDER BY created_at DESC, id DESC LIMIT 1

mapper.update:
UPDATE reports SET status='FAILED', error_message=#{message}, error_code=#{errorCode},
    error_stage=#{errorStage}, source_count=#{sourceCount}, processing_token=NULL, updated_at=#{now}
WHERE id=#{id} AND user_id=#{userId} AND deleted_at IS NULL AND status='PROCESSING' AND processing_token=#{token}

UPDATE reports SET manual_additions=#{manualAdditions}, version=version+1,
    manual_edited_at=#{now}, updated_at=#{now}
WHERE id=#{id} AND user_id=#{userId} AND deleted_at IS NULL AND status='SUCCEEDED' AND version=#{version}
